s":"24시간","has_accessible":"true","has_diaper_table":"false","has_emergency_bell":"true","has_cctv":"false","managing_org":"대구공공시설관리공단","phone":"053-254-9401"},{"id":"osm-w1194886773","mois_name":"용댐유원지(월안교)","is_always_open":"true","open_hours":"24시간","has_accessible":"false","has_diaper_table":"true","has_emergency_bell":"true","has_cctv":"true","managing_org":"창원시 마산합포구 환경과","phone":"055-220-4521"},{"id":"osm-w1265500410","mois_name":"레포츠공원","is_always_open":"true","open_hours":"24시간","has_accessible":"true","has_diaper_table":"true","has_emergency_bell":"true","has_cctv":"false","managing_org":"서산시청","phone":""},{"id":"osm-w1536664538","mois_name":"백약국옆","is_always_open":"true","open_hours":"24시간","has_accessible":"false","has_diaper_table":"false","has_emergency_bell":"true","has_cctv":"false","managing_org":"서산시청","phone":""}]$m$::jsonb)
    as x(id text, mois_name text, is_always_open text, open_hours text, has_accessible text,
         has_diaper_table text, has_emergency_bell text, has_cctv text, managing_org text, phone text)
), upd as (
  update public.toilets t set
    name = case when t.name in ('공중화장실','화장실','공용화장실','개방화장실') and nullif(s.mois_name,'') is not null
                then s.mois_name else t.name end,
    is_always_open     = t.is_always_open or s.is_always_open = 'true',
    open_hours         = coalesce(t.open_hours, nullif(s.open_hours,'')),
    has_accessible     = coalesce(t.has_accessible, nullif(s.has_accessible,'')::boolean),
    has_diaper_table   = coalesce(t.has_diaper_table, nullif(s.has_diaper_table,'')::boolean),
    has_emergency_bell = coalesce(t.has_emergency_bell, nullif(s.has_emergency_bell,'')::boolean),
    has_cctv           = coalesce(t.has_cctv, nullif(s.has_cctv,'')::boolean),
    managing_org       = coalesce(t.managing_org, nullif(s.managing_org,'')),
    phone              = coalesce(t.phone, nullif(s.phone,''))
  from src s where t.id = s.id
  returning t.id
)
select (select count(*) from src) as rows_in, (select count(*) from upd) as updated;
